export const SOURCES: Record<string, string> = {
  "server.ts": "/**\n * Copilot Runtime for this harness.\n *\n * Shape comes from the Angular quickstart's Node runtime server, with the\n * agent swapped for the AG2 backend in `../backend`.\n *\n * That backend exposes a plain AG-UI endpoint — `AGUIStream(agent)` mounted\n * with `app.mount(\"/agent\", stream.build_asgi())` in backend/main.py, the\n * shape the AG2 quickstart uses. It streams AG-UI events over SSE.\n *\n * The trailing slash in the URL below is load-bearing. A Starlette mount only\n * serves its own path with the slash: `POST /agent` answers `307` with a\n * `Location` of `/agent/`, and `HttpAgent` posts, does not re-post, and the\n * run dies with no events. See README known issues.\n *\n * `default` and `support` resolve to the same AG2 process.\n * `support` exists so the doc snippets that use `agentId=\"support\"` (Chat UI,\n * Threads) run verbatim.\n *\n * `a2ui: {}` enables A2UIMiddleware for every registered agent, per\n * https://docs.copilotkit.ai/angular/ag2/backend/copilot-runtime\n * — it is a runtime-side middleware and is independent of which agent binding\n * is used.\n *\n * Ports: the quickstart puts the runtime on 8400, but backend/main.py binds\n * that, so the runtime moved to 8401. Override either side with PORT /\n * AG2_AGENT_URL.\n */\n// quickstart : copilot runtime\nimport { createServer } from \"node:http\";\nimport { CopilotRuntime } from \"@copilotkit/runtime/v2\";\nimport { createCopilotNodeListener } from \"@copilotkit/runtime/v2/node\";\nimport { HttpAgent } from \"@ag-ui/client\";\n\nconst agentUrl =\n  process.env[\"AG2_AGENT_URL\"] ?? \"http://localhost:8400/agent/\";\n\n// quickstart : copilot runtime start\nconst runtime = new CopilotRuntime({\n  agents: {\n    // quickstart : connect selected agent backend\n    default: new HttpAgent({ url: agentUrl }),\n    // chat ui : support agent\n    support: new HttpAgent({ url: agentUrl }),\n  },\n  // a2ui : enable a2ui middleware start\n  a2ui: {},\n  // a2ui : enable a2ui middleware end\n});\n// quickstart : copilot runtime end\n\nconst port = Number(process.env[\"PORT\"] ?? 8401);\n\n// quickstart : create copilot node listener start\ncreateServer(\n  createCopilotNodeListener({\n    runtime,\n    basePath: \"/api/copilotkit\",\n    cors: true,\n  }),\n).listen(port, () => {\n  console.log(\n    `Copilot Runtime listening at http://localhost:${port}/api/copilotkit`,\n  );\n  console.log(`AG2 agent: ${agentUrl}`);\n});\n// quickstart : create copilot node listener end\n",
  "src/styles.css": "@import 'tailwindcss';\n\n/* Quickstart step \"Import the styles\". Self-contained — the chat renders\n   without any other CSS.\n   https://docs.copilotkit.ai/angular/ag2/quickstart */\n\n/* quickstart : import the styles start */\n@import '@copilotkit/angular/styles.css';\n\n/* ------------------------------------------------------------------ */\n/* Harness chrome tokens                                              */\n/* `--line` and `--muted` are referenced by the A2UI guide's CSS below, */\n/* which does not define them itself.                                  */\n/* ------------------------------------------------------------------ */\n:root {\n  /* Surfaces */\n  --bg: #f4f6fa;\n  --surface: #ffffff;\n  --surface-sunken: #eef1f7;\n\n  /* Text — all AA or better on --surface */\n  --ink: #0d1526;\n  --ink-soft: #33415a;\n  --muted: #5c6a86;\n\n  /* Lines */\n  --line: #e0e5ee;\n  --line-strong: #c6cedd;\n\n  /* Accent */\n  --accent: #4f46e5;\n  --accent-hover: #4338ca;\n  --accent-soft: #eef0ff;\n  --accent-ink: #362fa8;\n\n  /* Code surface */\n  --code-bg: #0b1220;\n  --code-bar: #131c2f;\n  --code-ink: #dbe3f0;\n  --code-line: #24304a;\n}\n\nhtml,\nbody {\n  height: 100%;\n  margin: 0;\n  color: var(--ink);\n  background: var(--bg);\n  font-family:\n    'Inter',\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    Roboto,\n    Helvetica,\n    Arial,\n    sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Visible keyboard focus everywhere in the harness chrome (WCAG 2.4.7). */\na:focus-visible,\nbutton:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n  border-radius: 0.375rem;\n}\n\n/* Inline code in prose — distinct from the dark code blocks. */\n.prose-inline-code,\np > code,\nli > code,\ntd > code {\n  padding: 0.1rem 0.35rem;\n  border: 1px solid var(--line);\n  border-radius: 0.3rem;\n  background: var(--surface-sunken);\n  color: var(--accent-ink);\n  font-size: 0.85em;\n}\n\n/* ------------------------------------------------------------------ */\n/* Code figures                                                        */\n/* ------------------------------------------------------------------ */\n.code-figure {\n  overflow: hidden;\n  border: 1px solid var(--code-line);\n  border-radius: 0.75rem;\n  background: var(--code-bg);\n  box-shadow: 0 12px 28px -22px rgb(11 18 32 / 0.65);\n}\n\n/* Quoted-from-docs samples read as secondary to the code that runs. */\n.code-figure--quoted {\n  border-style: dashed;\n  border-color: var(--line-strong);\n}\n\n.code-figure__bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem 1rem;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.5rem 0.85rem;\n  border-bottom: 1px solid var(--code-line);\n  background: var(--code-bar);\n}\n\n.code-figure__path-group {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.45rem;\n  min-width: 0;\n}\n\n.code-figure__path {\n  color: #b9c6de;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.72rem;\n  word-break: break-all;\n}\n\n.code-figure__copy-path,\n.code-figure__open-ide {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.3rem;\n  padding: 0.12rem 0.45rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: #141f33;\n  color: #a5b4cd;\n  font-size: 0.68rem;\n  font-weight: 500;\n  cursor: pointer;\n  text-decoration: none;\n  transition: all 0.15s ease;\n  line-height: 1.2;\n}\n\n.code-figure__copy-path:hover,\n.code-figure__open-ide:hover {\n  background: #22304d;\n  border-color: #3e517a;\n  color: #f1f5f9;\n}\n\n.code-figure__icon {\n  width: 0.85rem;\n  height: 0.85rem;\n  flex-shrink: 0;\n}\n\n.code-figure__meta {\n  display: flex;\n  flex-shrink: 0;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.code-figure__note {\n  color: #93a3c0;\n  font-size: 0.72rem;\n}\n\n.code-figure__lang,\n.code-figure__badge {\n  padding: 0.1rem 0.45rem;\n  border-radius: 999px;\n  background: #22304d;\n  color: #a9b8d6;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n}\n\n.code-figure__badge {\n  background: #3b2f18;\n  color: #e6c07b;\n}\n\n.code-figure__copy {\n  padding: 0.15rem 0.55rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: transparent;\n  color: #b9c6de;\n  font-size: 0.7rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.code-figure__copy:hover {\n  background: #22304d;\n  color: #e6edf9;\n}\n\n.code-figure__pre {\n  max-height: 32rem;\n  margin: 0;\n  overflow: auto;\n  padding: 1rem;\n  color: var(--code-ink);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.78rem;\n  line-height: 1.65;\n  tab-size: 2;\n}\n\n/* ------------------------------------------------------------------ */\n/* highlight.js theme — tuned for contrast on --code-bg                */\n/* ------------------------------------------------------------------ */\n.hljs-comment,\n.hljs-quote {\n  color: #8494b3;\n  font-style: italic;\n}\n\n.hljs-keyword,\n.hljs-selector-tag,\n.hljs-literal,\n.hljs-doctag {\n  color: #c4b5fd;\n}\n\n.hljs-string,\n.hljs-regexp,\n.hljs-addition {\n  color: #8ee7a5;\n}\n\n.hljs-number,\n.hljs-symbol,\n.hljs-bullet {\n  color: #fcd34d;\n}\n\n.hljs-title,\n.hljs-title.function_,\n.hljs-section {\n  color: #7dd3fc;\n}\n\n.hljs-title.class_,\n.hljs-type,\n.hljs-built_in,\n.hljs-class .hljs-title {\n  color: #fdba74;\n}\n\n.hljs-attr,\n.hljs-attribute,\n.hljs-property,\n.hljs-variable,\n.hljs-template-variable {\n  color: #f0abfc;\n}\n\n.hljs-name,\n.hljs-selector-id,\n.hljs-selector-class,\n.hljs-tag {\n  color: #fb7185;\n}\n\n.hljs-meta,\n.hljs-params,\n.hljs-punctuation {\n  color: #a5b4cd;\n}\n\n.hljs-deletion {\n  color: #fca5a5;\n}\n\n.hljs-emphasis {\n  font-style: italic;\n}\n\n.hljs-strong {\n  font-weight: 700;\n}\n\n/* chat ui : scope css changes start */\n.support-chat .copilotKitUserMessage {\n  color: white;\n  background: #2563eb;\n  border-radius: 0.75rem;\n}\n\n.support-chat .copilotKitAssistantMessage {\n  padding: 0.75rem;\n  color: #172554;\n  background: #eff6ff;\n  border-radius: 0.75rem;\n}\n/* chat ui : scope css changes end */\n\n/* a2ui : style rendered components start */\n.a2ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: stretch;\n  width: 100%;\n}\n\n.a2ui-row > * {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n.a2ui-column {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n\n[data-testid='declarative-card'],\n.a2ui-chart-card,\n.a2ui-flight-card {\n  display: block;\n  padding: 1rem;\n  border: 1px solid var(--line);\n  border-radius: 0.9rem;\n  background: white;\n  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);\n}\n\n.a2ui-metric {\n  display: grid;\n  min-width: 8rem;\n  gap: 0.25rem;\n}\n\n.a2ui-metric > span,\n.a2ui-metric > small {\n  color: var(--muted);\n  font-size: 0.75rem;\n}\n\n.a2ui-metric > strong {\n  font-size: 1.4rem;\n}\n\n.a2ui-status,\n.a2ui-airline {\n  display: inline-flex;\n  width: fit-content;\n  padding: 0.25rem 0.55rem;\n  border-radius: 999px;\n  background: #eef2ff;\n  font-size: 0.75rem;\n  font-weight: 700;\n}\n\n.a2ui-status-success {\n  background: #dcfce7;\n  color: #166534;\n}\n.a2ui-status-warning {\n  background: #fef3c7;\n  color: #92400e;\n}\n.a2ui-status-error {\n  background: #fee2e2;\n  color: #991b1b;\n}\n/* a2ui : style rendered components end */\n",
  "src/app/app.config.ts": "import {\n  ApplicationConfig,\n  provideBrowserGlobalErrorListeners,\n} from '@angular/core';\nimport { provideRouter, withInMemoryScrolling } from '@angular/router';\nimport { provideClientHydration } from '@angular/platform-browser';\nimport {\n  provideCopilotKit,\n  type SandboxFunction,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { routes } from './app.routes';\n\n// frontend tools : open generative ui host function start\nconst setDashboardFilter: SandboxFunction<{ filter: string }> = {\n  name: 'setDashboardFilter',\n  description: 'Set the active dashboard filter',\n  parameters: z.object({ filter: z.string() }),\n  handler: async ({ filter }) => {\n    sessionStorage.setItem('dashboard-filter', filter);\n    return { applied: filter };\n  },\n};\n// frontend tools : open generative ui host function end\n\n\n/**\n * One provider at the application root, so a conversation started on any demo\n * route continues on every other route.\n *\n * `runtimeUrl` points at the Copilot Runtime from the quickstart — the\n * supported path, where the browser never talks to the AG2 agent directly.\n * The `HttpAgent` binding that reaches the AG2 AG-UI endpoint lives\n * server-side in frontend/server.ts.\n *\n * `a2ui.recovery` and `openGenerativeUI.sandboxFunctions` are the A2UI and\n * generative-UI guide options. No `a2ui.catalog` is set yet — supplying one is\n * what actually registers the render_a2ui renderer, so A2UI stays inert until\n * a catalog is added. See README known issues.\n */\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    provideRouter(\n      routes,\n      withInMemoryScrolling({ scrollPositionRestoration: 'top' }),\n    ),\n    provideClientHydration(),\n    // quickstart : connect to copilot runtime start\n    provideCopilotKit({\n      runtimeUrl: 'http://localhost:8401/api/copilotkit',\n      // a2ui : recover incomplete streams start\n      a2ui: {\n        recovery: { showAfterMs: 2_000, showAfterAttempts: 2 },\n      },\n      // a2ui : recover incomplete streams end\n      // frontend tools : open generative ui start\n      openGenerativeUI: {\n        // `sandboxFunctions` is typed `SandboxFunction[]`, i.e.\n        // `SandboxFunction<Record<string, unknown>>[]`, so the guide's\n        // `SandboxFunction<{ filter: string }>` is not assignable to it as\n        // written. Cast at the array site, the same idiom the docs use for the\n        // equivalent `component` variance problem. See README known issues.\n        sandboxFunctions: [setDashboardFilter as unknown as SandboxFunction],\n      },\n      // frontend tools : open generative ui end\n    }),\n    // quickstart : connect to copilot runtime end\n  ],\n};\n",
  "src/app/features/a2ui/a2ui-chat.component.ts": "// a2ui : a2ui chat start\n/**\n * A2UI needs no component-level wiring: the runtime applies A2UIMiddleware\n * (`a2ui: {}` in frontend/server.ts) and, per the guide, \"on the frontend, the\n * A2UI renderer activates automatically. No extra configuration is needed.\"\n *\n * The recovery thresholds the guide prescribes are set once in\n * src/app/app.config.ts, and its catalog CSS lives in src/styles.css.\n * https://docs.copilotkit.ai/angular/ag2/guides/a2ui\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-a2ui-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class A2uiChatComponent {}\n// a2ui : a2ui chat end\n",
  "src/app/features/attachments/media-chat.component.ts": "// attachments : enable attachments start\n/**\n * \"Enable attachments\", verbatim. Without `onUpload`, files are read as base64\n * and travel inline with the message.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-media-chat',\n  imports: [CopilotChat],\n  template: ` <copilot-chat [attachments]=\"attachments\" /> `,\n})\nexport class MediaChatComponent {\n  // attachments : attachments config start\n  protected readonly attachments: AttachmentsConfig = {\n    enabled: true,\n    accept: 'image/*,application/pdf',\n    maxSize: 10 * 1024 * 1024,\n    onUploadFailed: (error) => {\n      console.error(error.reason, error.message);\n    },\n  };\n  // attachments : attachments config end\n}\n// attachments : enable attachments end\n",
  "src/app/features/chat-ui/chat-ui-demo.component.ts": "/**\n * Harness wrapper that mounts the guide's chat surfaces one at a time.\n *\n * The popup and the sidebar each get their own tab AND their own host\n * component. The guide declares both in a single component, but both render a\n * launcher at the same fixed coordinates, so mounting them together stacks two\n * launchers on one spot and the sidebar — rendered second — swallows every\n * click. The guide's combined component stays verbatim in\n * popup-sidebar.component.ts and is what the route page displays as source.\n *\n * Bindings on the split hosts are the guide's, unchanged.\n *\n * `.support-chat` is applied to the inline tab only. It is the scope class for\n * the guide's \"Scope CSS changes\" block, which repaints the message bubbles —\n * putting it on the shared host would tint the custom-message, popup, and\n * sidebar surfaces too, and each of those is meant to show its own default\n * styling.\n */\nimport { Component, signal } from '@angular/core';\n\nimport { CustomMessageChatComponent } from './custom-message-chat.component';\nimport { PopupOnlyComponent } from './popup-only.component';\nimport { SidebarOnlyComponent } from './sidebar-only.component';\nimport { SupportChatComponent } from './support-chat.component';\n\ntype Surface = 'inline' | 'custom-message' | 'popup' | 'sidebar';\n\n@Component({\n  selector: 'app-chat-ui-demo',\n  imports: [\n    SupportChatComponent,\n    CustomMessageChatComponent,\n    PopupOnlyComponent,\n    SidebarOnlyComponent,\n  ],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <div role=\"tablist\" aria-label=\"Chat surface\" class=\"flex flex-wrap gap-2\">\n        @for (tab of tabs; track tab.id) {\n          <button\n            type=\"button\"\n            role=\"tab\"\n            [attr.aria-selected]=\"surface() === tab.id\"\n            class=\"rounded-md border px-3 py-1.5 text-sm font-medium transition-colors\"\n            [class]=\"\n              surface() === tab.id\n                ? 'border-[var(--accent)] bg-[var(--accent)] text-white'\n                : 'border-[var(--line-strong)] bg-[var(--surface)] text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]'\n            \"\n            (click)=\"surface.set(tab.id)\"\n          >\n            {{ tab.label }}\n          </button>\n        }\n      </div>\n\n      <div class=\"min-h-0 flex-1\">\n        @switch (surface()) {\n          @case ('inline') {\n            <!-- Scope class for the guide's CSS block — this tab only. -->\n            <div class=\"support-chat h-full\">\n              <app-support-chat />\n            </div>\n          }\n          @case ('custom-message') {\n            <div class=\"h-full\">\n              <app-custom-message-chat />\n            </div>\n          }\n          @case ('popup') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-popup</code> opens from a floating launcher and\n                exposes a two-way <code>open</code> model, so the harness can\n                open it from here. It manages focus, closes on Escape, and\n                restores focus to the launcher.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"popupHost.popupOpen.set(!popupHost.popupOpen())\"\n              >\n                {{ popupHost.popupOpen() ? 'Close' : 'Open' }} popup\n              </button>\n              <app-popup-only #popupHost />\n            </div>\n          }\n          @case ('sidebar') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-sidebar</code> is docked to the right at 480px.\n                Compact viewports render it as a modal even when\n                <code>mode</code> is <code>\"docked\"</code>, and only one open\n                docked sidebar can own the page margin at a time.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"sidebarHost.sidebarOpen.set(!sidebarHost.sidebarOpen())\"\n              >\n                {{ sidebarHost.sidebarOpen() ? 'Close' : 'Open' }} sidebar\n              </button>\n              <app-sidebar-only #sidebarHost />\n            </div>\n          }\n        }\n      </div>\n    </div>\n  `,\n})\nexport class ChatUiDemoComponent {\n  protected readonly surface = signal<Surface>('inline');\n  protected readonly tabs: ReadonlyArray<{ id: Surface; label: string }> = [\n    { id: 'inline', label: 'Inline chat' },\n    { id: 'custom-message', label: 'Custom assistant message' },\n    { id: 'popup', label: 'Popup' },\n    { id: 'sidebar', label: 'Sidebar' },\n  ];\n}\n",
  "src/app/features/chat-ui/custom-assistant-message.component.ts": "// chat ui : replace an assistant message start\n/**\n * \"Replace an assistant message\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\n\nimport { ChangeDetectionStrategy, Component, input } from '@angular/core';\n\ntype AssistantMessage = {\n  id: string;\n  role: 'assistant';\n  content?: string;\n};\n\n@Component({\n  selector: 'app-custom-assistant-message',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article class=\"answer\">\n      <span class=\"answer__label\">Assistant</span>\n      <p>{{ message().content }}</p>\n    </article>\n  `,\n})\nexport class CustomAssistantMessageComponent {\n  readonly message = input.required<AssistantMessage>();\n}\n// chat ui : replace an assistant message end\n",
  "src/app/features/chat-ui/custom-message-chat.component.ts": "// chat ui : replace an assistant message component start\n/**\n * The second `SupportChatComponent` from \"Replace an assistant message\",\n * verbatim except for the class name and selector — the guide gives two\n * different components the same name and selector, and both are mounted here.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { CustomAssistantMessageComponent } from './custom-assistant-message.component';\n\n@Component({\n  selector: 'app-custom-message-chat',\n  imports: [CopilotChat],\n  template: `\n    <copilot-chat\n      [assistantMessageComponent]=\"assistantMessageComponent\"\n      assistantMessageClass=\"support-answer\"\n    />\n  `,\n})\nexport class CustomMessageChatComponent {\n  protected readonly assistantMessageComponent =\n    CustomAssistantMessageComponent;\n}\n// chat ui : replace an assistant message component end\n",
  "src/app/features/chat-ui/popup-only.component.ts": "// chat ui : use a popup start\n/**\n * The popup half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * The guide declares `copilot-popup` and `copilot-sidebar` in one component.\n * Both render a launcher at the same fixed coordinates\n * (`right: max(1.5rem, …); bottom: max(1.5rem, …)`), so mounting them together\n * stacks two launchers on one spot and the sidebar — rendered second — takes\n * every click. Splitting them is what makes each surface separately testable;\n * the combined component is kept verbatim in popup-sidebar.component.ts and\n * shown as the source on the route page.\n *\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-only',\n  imports: [CopilotPopup],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n  `,\n})\nexport class PopupOnlyComponent {\n  readonly popupOpen = signal(false);\n}\n// chat ui : use a popup end\n",
  "src/app/features/chat-ui/popup-sidebar.component.ts": "// chat ui : use a popup or sidebar start\n/**\n * \"Use a popup or sidebar\", verbatim except for the class name and selector\n * (the guide mounts it as `AppComponent` / `app-root`).\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup, CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-sidebar',\n  imports: [CopilotPopup, CopilotSidebar],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class PopupSidebarComponent {\n  readonly popupOpen = signal(false);\n  readonly sidebarOpen = signal(false);\n}\n// chat ui : use a popup or sidebar end\n",
  "src/app/features/chat-ui/sidebar-only.component.ts": "// chat ui : use a sidebar start\n/**\n * The sidebar half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * See popup-only.component.ts for why the guide's combined component is split\n * for the demo: both surfaces render a launcher at the same fixed coordinates.\n *\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport { CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-sidebar-only',\n  imports: [CopilotSidebar],\n  template: `\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class SidebarOnlyComponent {\n  readonly sidebarOpen = signal(false);\n}\n// chat ui : use a sidebar end\n",
  "src/app/features/chat-ui/support-chat.component.ts": "// chat ui : add an inline chat start\n/**\n * \"Add an inline chat\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n *\n * `agentId=\"support\"` resolves because the runtime registers a `support` agent\n * alongside `default` (see frontend/server.ts).\n */\n\nimport { ChangeDetectionStrategy, Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-support-chat',\n  imports: [CopilotChat],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"chat-shell\" aria-label=\"Support assistant\">\n      <copilot-chat agentId=\"support\" />\n    </section>\n  `,\n  styles: `\n    .chat-shell {\n      height: min(48rem, 80vh);\n      overflow: hidden;\n      border: 1px solid #dbe3eb;\n      border-radius: 1rem;\n    }\n  `,\n})\nexport class SupportChatComponent {}\n// chat ui : add an inline chat end\n",
  "src/app/features/headless/headless-chat.component.ts": "// headless : build a headless chat start\n/**\n * \"Build a headless chat\", verbatim. No CopilotKit chrome: the transcript and\n * composer are hand-written over `injectAgentStore`, and the run is driven\n * through `CopilotKitCore.runAgent`.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\n\nimport { Component, inject, signal } from '@angular/core';\nimport { CopilotKit, injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-headless-chat',\n  template: `\n    <div aria-live=\"polite\">\n      @for (message of store().messages(); track message.id) {\n        <article [attr.data-role]=\"message.role\">\n          {{ message.content }}\n        </article>\n      }\n      @if (store().isRunning()) {\n        <p>Agent is working…</p>\n      }\n    </div>\n\n    <textarea\n      aria-label=\"Message\"\n      [value]=\"draft()\"\n      (input)=\"updateDraft($event)\"\n    ></textarea>\n    <button\n      type=\"button\"\n      [disabled]=\"store().isRunning() || !draft().trim()\"\n      (click)=\"send()\"\n    >\n      Send\n    </button>\n  `,\n})\nexport class HeadlessChatComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  // headless : inject agent store start\n  readonly store = injectAgentStore('default');\n  // headless : inject agent store end\n  readonly draft = signal('');\n\n  protected updateDraft(event: Event): void {\n    this.draft.set((event.target as HTMLTextAreaElement).value);\n  }\n\n  protected async send(): Promise<void> {\n    const content = this.draft().trim();\n    if (!content || this.store().isRunning()) return;\n\n    const agent = this.store().agent;\n    agent.addMessage({\n      id: crypto.randomUUID(),\n      role: 'user',\n      content,\n    });\n    this.draft.set('');\n    // headless : run agent start\n    await this.copilotKit.core.runAgent({ agent });\n    // headless : run agent end\n  }\n}\n// headless : build a headless chat end\n",
  "src/app/features/hitl/approval-card.component.ts": "// human in the loop : register a decision tool renderer start\n/**\n * \"Register a decision tool\" renderer, verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n */\n\nimport { Component, input } from '@angular/core';\nimport {\n  type HumanInTheLoopToolCall,\n  type HumanInTheLoopToolRenderer,\n} from '@copilotkit/angular';\n\ntype ApprovalArgs = {\n  action: string;\n  reason: string;\n};\n\n@Component({\n  selector: 'app-approval-card',\n  template: `\n    @let call = toolCall();\n    <article>\n      <h3>Approve {{ call.args.action ?? \"this action\" }}?</h3>\n      <p>{{ call.args.reason }}</p>\n\n      @if (call.status !== \"complete\") {\n        <button type=\"button\" (click)=\"call.respond({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"call.respond({ approved: false })\">\n          Reject\n        </button>\n      }\n    </article>\n  `,\n})\nexport class ApprovalCardComponent\n  implements HumanInTheLoopToolRenderer<ApprovalArgs>\n{\n  readonly toolCall = input.required<HumanInTheLoopToolCall<ApprovalArgs>>();\n}\n// human in the loop : register a decision tool renderer end\n",
  "src/app/features/hitl/approval-tools.service.ts": "// human in the loop : register a decision tool service start\n/**\n * \"Register the tool from the component or service that owns the decision UI\",\n * verbatim. There is no handler — CopilotKit supplies one that waits for\n * `respond`, returns the decision to the agent, and continues the run.\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n */\n\nimport { Injectable } from '@angular/core';\nimport { registerHumanInTheLoop } from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { ApprovalCardComponent } from './approval-card.component';\n\n@Injectable()\nexport class ApprovalToolsService {\n  constructor() {\n    // human in the loop : register human in the loop tool start\n    registerHumanInTheLoop({\n      name: 'requestApproval',\n      description: 'Ask the user before a consequential action',\n      parameters: z.object({\n        action: z.string(),\n        reason: z.string(),\n      }),\n      component: ApprovalCardComponent,\n    });\n    // human in the loop : register human in the loop tool end\n  }\n}\n// human in the loop : register a decision tool service end\n",
  "src/app/features/hitl/hitl-chat.component.ts": "// human in the loop : hitl chat start\n/**\n * Puts the guide's three human-in-the-loop paths side by side: the decision\n * tool (registered by ApprovalToolsService, rendered inside the chat's\n * tool-call flow), the headless interrupt controller, and the store's own\n * controller — the last two rendered outside the chat and pointed at different\n * agents, as the guide's warning requires.\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n *\n * Injecting ApprovalToolsService is what constructs it, and construction is\n * what performs the `registerHumanInTheLoop` call.\n */\n\nimport { Component, inject } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { ApprovalToolsService } from './approval-tools.service';\nimport { InterruptPanelComponent } from './interrupt-panel.component';\nimport { TicketApprovalComponent } from './ticket-approval.component';\n\n@Component({\n  selector: 'app-hitl-chat',\n  imports: [CopilotChat, InterruptPanelComponent, TicketApprovalComponent],\n  providers: [ApprovalToolsService],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <app-interrupt-panel />\n      <app-ticket-approval />\n      <div style=\"flex: 1; min-height: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class HitlChatComponent {\n  private readonly approvalTools = inject(ApprovalToolsService);\n}\n// human in the loop : hitl chat end\n",
  "src/app/features/hitl/interrupt-panel.component.ts": "// human in the loop : handle an interrupt start\n/**\n * \"Handle an interrupt\", verbatim. The controller is headless, so this panel\n * renders nothing until the backend emits an AG-UI interrupt.\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n */\n\nimport { Component } from '@angular/core';\nimport { injectInterrupt } from '@copilotkit/angular';\n\ntype ReviewRequest = {\n  title?: string;\n  choices?: Array<{ id: string; label: string }>;\n};\n\n@Component({\n  selector: 'app-interrupt-panel',\n  template: `\n    @if (controller.event(); as event) {\n      @let request = asReviewRequest(event.value);\n      <section aria-labelledby=\"review-title\">\n        <h2 id=\"review-title\">{{ request.title ?? \"Review required\" }}</h2>\n\n        @for (choice of request.choices ?? []; track choice.id) {\n          <button type=\"button\" (click)=\"resolve(choice.id)\">\n            {{ choice.label }}\n          </button>\n        }\n\n        <button type=\"button\" (click)=\"cancel()\">Cancel</button>\n      </section>\n    }\n\n    @if (controller.error()) {\n      <p role=\"alert\">The decision could not be submitted.</p>\n    }\n  `,\n})\nexport class InterruptPanelComponent {\n  // DIVERGENCE RESOLVED at @copilotkit/angular@0.4.0 — the doc's own form runs.\n  //\n  // The doc's snippet passes the agent id as a string:\n  //\n  //     injectInterrupt<ReviewRequest>('default');\n  //\n  // That did not compile against @copilotkit/angular@0.3.1, whose declaration\n  // took an options object and had no string overload:\n  //\n  //     declare function injectInterrupt<TValue, TResult>(\n  //       options?: InjectInterruptOptions<TValue, TResult>\n  //     ): InterruptController<TValue, TResult>;\n  //\n  //   TS2559: Type '\"default\"' has no properties in common with type\n  //           'InjectInterruptOptions<ReviewRequest, never>'\n  //\n  // This file carried the object form for as long as that was true, because one\n  // compile error blocks every recording, not just this page. 0.4.0 publishes\n  // the string-first overload:\n  //\n  //     declare function injectInterrupt<TValue, TResult>(\n  //       agentId?: InterruptAgentId,\n  //       options?: Omit<InjectInterruptOptions<TValue, TResult>, \"agentId\">\n  //     ): InterruptController<TValue, TResult>;\n  //\n  // The finding stands as a doc-ahead-of-release defect — the page carried no\n  // version note while the snippet was uncompilable — but it no longer blocks.\n  //\n  // human in the loop : inject interrupt start\n  protected readonly controller = injectInterrupt<ReviewRequest>('default');\n  // human in the loop : inject interrupt end\n\n  protected asReviewRequest(value: unknown): ReviewRequest {\n    return typeof value === 'object' && value !== null\n      ? (value as ReviewRequest)\n      : {};\n  }\n\n  protected resolve(choiceId: string): void {\n    this.controller.resolve({ choiceId }).catch(() => undefined);\n  }\n\n  protected cancel(): void {\n    this.controller.cancel().catch(() => undefined);\n  }\n}\n// human in the loop : handle an interrupt end\n",
  "src/app/features/hitl/ticket-approval.component.ts": "// human in the loop : ticket approval start\n/**\n * \"Handle an interrupt from the store\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n *\n * Unimplementable until now: `AgentStore` shipped only `agent`, `isRunning`,\n * `messages` and `state` in `@copilotkit/angular@0.3.1`, so\n * `store().interruptController` did not exist for as long as the section\n * described it. `0.4.0` adds `readonly interruptController: InterruptController`\n * and the snippet compiles as published.\n *\n * One deviation: the doc injects the store for an agent named `ticketing`. No\n * such agent is registered here, and an unknown id resolves to a store whose\n * controller never sees an event — which would make this component look healthy\n * while testing nothing. It uses `support`, the second agent this repo's\n * runtime registers, which also keeps it off `default` and so honours the\n * guide's own warning against pointing `injectInterrupt` and\n * `store().interruptController` at one decision: the sibling\n * `app-interrupt-panel` holds `default`.\n */\n\nimport { Component } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-ticket-approval',\n  template: `\n    @let interrupts = store().interruptController;\n\n    @if (interrupts.hasInterrupt()) {\n      <section>\n        <p>{{ interrupts.interrupt()?.message }}</p>\n        <button type=\"button\" (click)=\"interrupts.resolve({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"interrupts.cancel()\">Reject</button>\n      </section>\n    }\n  `,\n})\nexport class TicketApprovalComponent {\n  protected readonly store = injectAgentStore('support');\n}\n// human in the loop : ticket approval end\n",
  "src/app/features/media/voice-chat.component.ts": "// voice & multimodal : accept voice input and configure attachments start\n/**\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\n * config bound to the chat exactly as its `media-chat.component.html` snippet\n * shows. The microphone control needs no option — it is always present.\n * https://docs.copilotkit.ai/angular/ag2/guides/voice-multimodal\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n// voice & multimodal : configure attachments start\nconst MULTIMODAL_ATTACHMENTS: AttachmentsConfig = {\n  enabled: true,\n  accept: 'image/*,application/pdf',\n  maxSize: 10 * 1024 * 1024,\n};\n// voice & multimodal : configure attachments end\n\n@Component({\n  selector: 'app-voice-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat [attachments]=\"multimodalAttachments\" />\n    </div>\n  `,\n})\nexport class VoiceChatComponent {\n  protected readonly multimodalAttachments = MULTIMODAL_ATTACHMENTS;\n}\n// voice & multimodal : accept voice input and configure attachments end\n",
  "src/app/features/memory/memory-demo.component.ts": "/**\n * Harness wrapper mounting the guide's memory list beside a chat, so the\n * `isAvailable()` gate can be observed against a live runtime.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { MemoryListComponent } from './memory-list.component';\n\n@Component({\n  selector: 'app-memory-demo',\n  imports: [CopilotChat, MemoryListComponent],\n  template: `\n    <div class=\"flex h-full gap-4 p-4\">\n      <section\n        class=\"w-80 shrink-0 overflow-y-auto rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          injectMemories\n        </h2>\n        <app-memory-list />\n      </section>\n      <div class=\"min-w-0 flex-1\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class MemoryDemoComponent {}\n",
  "src/app/features/memory/memory-list.component.ts": "// memory : read and manage memory start\n/**\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\n * config bound to the chat exactly as its `media-chat.component.html` snippet\n * shows. The microphone control needs no option — it is always present.\n * https://docs.copilotkit.ai/angular/ag2/guides/voice-multimodal\n */\n\nimport { Component } from '@angular/core';\nimport { injectMemories } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-memory-list',\n  template: `\n    @if (!memory.isAvailable()) {\n      <p>Memory is not available for this runtime.</p>\n    } @else {\n      @for (item of memory.memories(); track item.id) {\n        <article>\n          <p>{{ item.content }}</p>\n          <button type=\"button\" (click)=\"remove(item.id)\">Forget</button>\n        </article>\n      }\n    }\n  `,\n})\nexport class MemoryListComponent {\n  // memory : inject memories start\n  readonly memory = injectMemories();\n  // memory : inject memories end\n\n  protected remove(id: string): void {\n    this.memory.removeMemory(id).catch(() => undefined);\n  }\n\n  protected addPreference(): void {\n    this.memory\n      .addMemory({\n        kind: 'operational',\n        content: 'Prefer concise status updates.',\n      })\n      .catch(() => undefined);\n  }\n}\n// memory : read and manage memory end\n",
  "src/app/features/quickstart/quickstart-chat.ts": "// quickstart : add the chat ui start\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-quickstart-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100vh\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class QuickstartChat {}\n// quickstart : add the chat ui end\n",
  "src/app/features/shared-state/account-context.component.ts": "// shared state : send read-only application context start\n/**\n * \"Send read-only application context\", verbatim. The accessor form keeps the\n * signal reads reactive, so changing the timezone re-registers the context.\n * https://docs.copilotkit.ai/angular/ag2/guides/shared-state\n */\n\nimport { Component, signal } from '@angular/core';\nimport { connectAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-account-context',\n  template: `\n    <br>\n    <button type=\"button\" (click)=\"timezone.set('Europe/London')\">\n      Use London time\n    </button>\n  `,\n})\nexport class AccountContextComponent {\n  readonly userName = signal('Ada');\n  readonly timezone = signal('America/Los_Angeles');\n\n  constructor() {\n    connectAgentContext(() => ({\n      description: 'Current account and timezone',\n      value: JSON.stringify({\n        userName: this.userName(),\n        timezone: this.timezone(),\n      }),\n    }));\n  }\n}\n// shared state : send read-only application context end\n",
  "src/app/features/shared-state/selection-context.component.ts": "// shared state : bind context in a template start\n/**\n * \"Bind context in a template\", verbatim. The directive registers on first\n * render, so it must not be rendered before the context is complete.\n * https://docs.copilotkit.ai/angular/ag2/guides/shared-state\n */\n\nimport { Component, computed, signal } from '@angular/core';\nimport { CopilotKitAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-selection-context',\n  imports: [CopilotKitAgentContext],\n  template: ` <div [copilotkitAgentContext]=\"selectionContext()\"></div> `,\n})\nexport class SelectionContextComponent {\n  readonly selectedId = signal('record-42');\n  readonly selectionContext = computed(() => ({\n    description: 'The record selected in the application',\n    value: this.selectedId(),\n  }));\n}\n// shared state : bind context in a template end\n",
  "src/app/features/shared-state/shared-state-chat.component.ts": "// shared state : shared state chat start\n/**\n * Mounts the guide's three surfaces against one chat: the read/write state\n * panel, the accessor-based context, and the directive-based context.\n * https://docs.copilotkit.ai/angular/ag2/guides/shared-state\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AccountContextComponent } from './account-context.component';\nimport { SelectionContextComponent } from './selection-context.component';\nimport { WorkspaceComponent } from './workspace.component';\n\n@Component({\n  selector: 'app-shared-state-chat',\n  imports: [\n    CopilotChat,\n    WorkspaceComponent,\n    AccountContextComponent,\n    SelectionContextComponent,\n  ],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-workspace />\n        <app-account-context />\n        <app-selection-context />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class SharedStateChatComponent {}\n// shared state : shared state chat end\n",
  "src/app/features/shared-state/workspace.component.ts": "// shared state : read and write agent state start\n/**\n * \"Read agent state\", verbatim. Reads through `store().state()` so Angular\n * tracks changes; writes through the plain AG-UI agent at `store().agent`.\n * https://docs.copilotkit.ai/angular/ag2/guides/shared-state\n */\n\nimport { Component, computed } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\ntype WorkspaceState = {\n  notes: string[];\n  priority: 'low' | 'normal' | 'high';\n};\n\nconst EMPTY_STATE: WorkspaceState = {\n  notes: [],\n  priority: 'normal',\n};\n\n@Component({\n  selector: 'app-workspace',\n  template: `\n    <p>Priority: {{ state().priority }}</p>\n    <ul>\n      @for (note of state().notes; track note) {\n        <li>{{ note }}</li>\n      }\n    </ul>\n    <button type=\"button\" (click)=\"setPriority('high')\">\n      Mark high priority\n    </button>\n    <br>\n     <button type=\"button\" (click)=\"setPriority('low')\">\n      Mark low priority\n    </button>\n  `,\n})\nexport class WorkspaceComponent {\n  readonly store = injectAgentStore('default');\n  readonly state = computed(\n    () => (this.store().state() as WorkspaceState | undefined) ?? EMPTY_STATE,\n  );\n\n  protected setPriority(priority: WorkspaceState['priority']): void {\n    const agent = this.store().agent;\n    const current = (agent.state as WorkspaceState | undefined) ?? EMPTY_STATE;\n    agent.setState({ ...current, priority });\n  }\n}\n// shared state : read and write agent state end\n",
  "src/app/features/threads/conversations.component.ts": "// threads : threads drawer and chat start\n/**\n * The drawer-plus-chat sample, verbatim. Both sit under one\n * `provideCopilotChatConfiguration`, which is what makes selection and\n * new-thread actions in the drawer update the chat.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport {\n  CopilotChat,\n  CopilotThreadsDrawer,\n  provideCopilotChatConfiguration,\n} from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-conversations',\n  imports: [CopilotChat, CopilotThreadsDrawer],\n  providers: [provideCopilotChatConfiguration({ agentId: 'support' })],\n  template: `\n    <copilot-threads-drawer agentId=\"support\" [limit]=\"20\" />\n    <copilot-chat />\n  `,\n})\nexport class ConversationsComponent {}\n// threads : threads drawer and chat end\n",
  "src/app/features/threads/thread-list.component.ts": "// threads : custom thread list start\n/**\n * \"For a custom thread list, use injectThreads\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport { injectThreads } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-thread-list',\n  template: `\n    <button type=\"button\" (click)=\"threads.startNewThread()\">\n      New conversation\n    </button>\n\n    @if (threads.isLoading()) {\n      <p>Loading conversations…</p>\n    } @else {\n      @for (thread of threads.threads(); track thread.id) {\n        <button type=\"button\" (click)=\"select(thread.id)\">\n          {{ thread.name ?? \"Untitled conversation\" }}\n        </button>\n      }\n    }\n\n    @if (threads.listError()) {\n      <button type=\"button\" (click)=\"threads.refetchThreads()\">Retry</button>\n    }\n  `,\n})\nexport class ThreadListComponent {\n  // threads : inject threads start\n  readonly threads = injectThreads({\n    agentId: 'support',\n    limit: 20,\n  });\n  // threads : inject threads end\n\n  protected select(threadId: string): void {\n    // Store this id and bind it to CopilotChat's threadId input.\n    console.log(threadId);\n  }\n}\n// threads : custom thread list end\n",
  "src/app/features/threads/threads-demo.component.ts": "/**\n * Harness wrapper mounting both thread surfaces from the guide: the hand-built\n * list on `injectThreads`, and the drop-in drawer beside a chat.\n */\nimport { Component } from '@angular/core';\n\nimport { ConversationsComponent } from './conversations.component';\nimport { ThreadListComponent } from './thread-list.component';\n\n@Component({\n  selector: 'app-threads-demo',\n  imports: [ThreadListComponent, ConversationsComponent],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <section class=\"rounded-lg border border-slate-200 bg-white p-4\">\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          Headless list — injectThreads\n        </h2>\n        <app-thread-list />\n      </section>\n\n      <section\n        class=\"flex min-h-0 flex-1 flex-col rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          CopilotThreadsDrawer + chat\n        </h2>\n        <div class=\"flex min-h-0 flex-1 gap-4\">\n          <app-conversations />\n        </div>\n      </section>\n    </div>\n  `,\n})\nexport class ThreadsDemoComponent {}\n",
  "src/app/features/tools/tool-feature-model.ts": "// frontend tools : register a browser tool (change_background) start\n/**\n * The guide's `change_background` frontend tool.\n * https://docs.copilotkit.ai/angular/ag2/guides/frontend-tools-generative-ui\n *\n * `createBackgroundTool` is the guide's function, unchanged. Everything above\n * it is not in the guide: the snippet is quoted from the live Showcase without\n * its `BackgroundToolArgs` type, its `resolveGradient` helper, or its imports,\n * so those are defined here to make it runnable.\n */\n\nimport { type WritableSignal } from '@angular/core';\nimport { type FrontendToolConfig } from '@copilotkit/angular';\nimport { z } from 'zod';\n\n/** Arguments the agent may send to `change_background`. */\nexport type BackgroundToolArgs = {\n  background?: string;\n  color?: string;\n};\n\n/** Named presets so the agent can ask for a look without writing CSS. */\nconst GRADIENT_PRESETS: Record<string, string> = {\n  blue: 'linear-gradient(180deg, #0c4a6e 0%, #38bdf8 100%)',\n  violet: 'linear-gradient(180deg, #4c1d95 0%, #c084fc 100%)',\n  sunset: 'linear-gradient(180deg, #f97316 0%, #db2777 55%, #7c3aed 100%)',\n  forest: 'linear-gradient(180deg, #14532d 0%, #4ade80 100%)',\n  slate: 'linear-gradient(180deg, #0f172a 0%, #475569 100%)',\n};\n\nexport const DEFAULT_BACKGROUND = GRADIENT_PRESETS['slate'];\n\n/**\n * Accept a preset name, a bare CSS color, or a full gradient and always return\n * something safe to drop into a `background` style binding.\n */\nexport function resolveGradient(value: string | undefined): string {\n  const raw = value?.trim();\n  if (!raw) {\n    return DEFAULT_BACKGROUND;\n  }\n\n  const preset = GRADIENT_PRESETS[raw.toLowerCase()];\n  if (preset) {\n    return preset;\n  }\n\n  return raw.includes('gradient(')\n    ? raw\n    : `linear-gradient(180deg, ${raw} 0%, ${raw} 100%)`;\n}\n\n/** Create the frontend tool that applies a requested CSS gradient. */\nexport function createBackgroundTool(\n  background: WritableSignal<string>,\n): FrontendToolConfig<BackgroundToolArgs> {\n  return {\n    name: 'change_background',\n    description: 'Change the application background to a CSS gradient.',\n    parameters: z.object({\n      background: z.string().optional(),\n      color: z.string().optional(),\n    }),\n    handler: async (args) => {\n      const next = resolveGradient(args.background ?? args.color);\n      background.set(next);\n      return { background: next };\n    },\n  };\n}\n// frontend tools : register a browser tool (change_background) end\n",
  "src/app/features/tools/tools-chat.component.ts": "// frontend tools : register tools and renderers start\n/**\n * Mounts both halves of the guide's frontend-tools section against one chat.\n *\n * `registerRenderToolCall` — the tool runs on the server (the AG2\n * agent's weather tool) and the browser only renders its call, through\n * WeatherCardComponent.\n *\n * `registerFrontendTool` — the tool runs in the browser. `change_background`\n * has a handler and no component, so it renders nothing in chat; its result is\n * the page itself changing. The registration is removed when this injector is\n * destroyed.\n *\n * The guide's other `registerFrontendTool` sample is a second `getWeather`\n * that runs in the browser. It is not mounted: it would collide with the\n * server-side tool of the same name, and it calls an `/api/weather` endpoint\n * this repo does not serve.\n *\n * https://docs.copilotkit.ai/angular/ag2/guides/frontend-tools-generative-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport {\n  CopilotSidebar,\n  registerFrontendTool,\n  registerRenderToolCall,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport {\n  DEFAULT_BACKGROUND,\n  createBackgroundTool,\n} from './tool-feature-model';\nimport { WeatherCardComponent } from './weather-card.component';\n\n@Component({\n  selector: 'app-tools-chat',\n  imports: [CopilotSidebar],\n  template: `\n    <div\n      style=\"height: 100%; display: flex; flex-direction: column; gap: 0.75rem; padding: 0.75rem; transition: background 400ms ease\"\n      [style.background]=\"background()\"\n    >\n        <copilot-sidebar />\n\n    </div>\n  `,\n})\nexport class ToolsChatComponent {\n  /** Written by the agent through the change_background handler. */\n  protected readonly background = signal(DEFAULT_BACKGROUND);\n\n  constructor() {\n    // frontend tools : render a tool result start\n    registerRenderToolCall({\n      name: 'getWeather',\n      args: z.object({ city: z.string() }),\n      component: WeatherCardComponent,\n    });\n    // frontend tools : render a tool result end\n\n    // frontend tools : register a browser tool start\n    registerFrontendTool(createBackgroundTool(this.background));\n    // frontend tools : register a browser tool end\n  }\n}\n// frontend tools : register tools and renderers end\n",
  "src/app/features/tools/weather-card.component.ts": "// frontend tools : render a tool result start\n/**\n * \"Render a tool result\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/frontend-tools-generative-ui\n */\n\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype WeatherArgs = { city: string };\n\n@Component({\n  selector: 'app-weather-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"complete\") {\n      <article>\n        <strong>{{ call.args.city }}</strong>\n        <p>{{ call.result }}</p>\n      </article>\n    } @else {\n      <p>Loading weather for {{ call.args.city ?? \"…\" }}</p>\n    }\n    <p>Tool Call done </p>\n  `,\n})\nexport class WeatherCardComponent implements ToolRenderer<WeatherArgs> {\n  readonly toolCall = input.required<AngularToolCall<WeatherArgs>>();\n}\n// frontend tools : render a tool result end\n",
  "../backend/main.py": "# quickstart : connect the selected agent backend\n\"\"\"AG2 agent exposed over AG-UI, for the CopilotKit Angular harness.\n\nShape comes from the AG2 quickstart's backend\n(https://docs.copilotkit.ai/ag2/quickstart, ag2ai/ag2-samples `weather.py`):\nan `ag2.Agent`, wrapped in `AGUIStream`, mounted on FastAPI as an ASGI\nendpoint that streams AG-UI events over SSE.\n\nThe tools here are the ones the Angular guide pages call for, not the samples\nrepo's Open-Meteo set:\n\n* `getWeather` — the server-side tool the Frontend tools & generative UI guide\n  renders with an Angular component.\n* `update_language` — the write half of the Shared state guide. AG2 has no\n  `state_schema`; shared state is the agent's context variables, and a tool\n  mutates them through `Context`.\n\nPort 8400, so the Copilot Runtime (8401) and the other harnesses in this\nworkspace can run beside it.\n\"\"\"\nfrom __future__ import annotations\n\nimport os\nfrom typing import Annotated\n\nimport uvicorn\nfrom ag2 import Agent, Context, Variable, tool\nfrom ag2.ag_ui import AGUIStream\nfrom ag2.config import OpenAIConfig\nfrom dotenv import load_dotenv\nfrom fastapi import FastAPI\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom pydantic import Field\n\nload_dotenv()\n\n# shared state : agent variables start\n# AG2's AG-UI bridge publishes the agent's context variables as the AG-UI\n# STATE_SNAPSHOT, so this dict is what `injectAgentStore(...).state()` reads on\n# the Angular side. There is no separate state schema to declare.\nINITIAL_VARIABLES: dict[str, object] = {\n    \"language\": \"english\",\n}\n# shared state : agent variables end\n\n\n# frontend tools : server tool getWeather start\n@tool(\n    name=\"getWeather\",\n    description=\"Get the weather for a location.\",\n)\ndef get_weather(\n    location: Annotated[str, Field(description=\"The location to get weather for\")],\n) -> str:\n    normalized = location.strip() or \"the requested location\"\n    return f\"The weather for {normalized} is 70 degrees.\"\n# frontend tools : server tool getWeather end\n\n\n# shared state : update language tool start\n@tool(\n    name=\"update_language\",\n    description=\"Set the user's preferred language: 'english' or 'spanish'.\",\n)\ndef update_language(\n    language: Annotated[\n        str, Field(description=\"Preferred language: 'english' or 'spanish'\")\n    ],\n    context: Context,\n) -> str:\n    normalized = (language or \"\").strip().lower()\n    if normalized not in (\"english\", \"spanish\"):\n        return \"Language unchanged. Use 'english' or 'spanish'.\"\n    # Writing the context variable is what moves shared state: the bridge emits\n    # a STATE_SNAPSHOT after the run when the variables differ from the ones it\n    # started with.\n    context.variables[\"language\"] = normalized\n    return f\"Language updated to {normalized}.\"\n# shared state : update language tool end\n\n\ndef _env(name: str, default: str = \"\") -> str:\n    \"\"\"Read an env var and strip surrounding whitespace.\n\n    The strip is not cosmetic. A secret pasted into a CI provider or a .env with\n    a trailing newline produces `Bearer sk-...\\n`, which httpx rejects as an\n    illegal header value before the request is ever sent. That surfaces as\n    openai.APIConnectionError -> the AG-UI stream raises -> the socket closes\n    mid-response -> the Copilot Runtime dies on an unhandled fetch error, and\n    every page in the browser reports \"Failed to fetch\".\n\n    One invisible character, and the visible symptom is three processes away\n    from it. This cost a full CI recording run, so the fix lives here rather\n    than in a runbook.\n    \"\"\"\n    return (os.getenv(name) or default).strip()\n\n\ndef _build_config() -> OpenAIConfig:\n    api_key = _env(\"OPENAI_API_KEY\")\n    if not api_key:\n        raise RuntimeError(\"Set OPENAI_API_KEY (see backend/.env.example).\")\n\n    # Fail loudly on a key that cannot work, rather than at the first model\n    # call: an OpenAI key is ASCII and unbroken, so anything else here means the\n    # value was mangled in transit and no request built from it will succeed.\n    if any(c.isspace() for c in api_key) or not api_key.isascii():\n        raise RuntimeError(\n            \"OPENAI_API_KEY contains whitespace or non-ASCII characters. \"\n            \"It was probably pasted with a line break. Re-add it as a single \"\n            \"unbroken line. (The key itself is not printed here on purpose.)\"\n        )\n\n    return OpenAIConfig(\n        model=_env(\"OPENAI_CHAT_MODEL_ID\", \"gpt-4o-mini\"),\n        api_key=api_key,\n        streaming=True,\n    )\n\n\n# shared state : prompt reads the shared variable start\ndef system_prompt(language: Annotated[str, Variable(default=\"english\")]) -> str:\n    \"\"\"A callable prompt, so the agent reads shared state on every turn.\n\n    AG2 resolves a `Variable`-annotated parameter from the same context\n    variables the AG-UI bridge publishes as STATE_SNAPSHOT. That makes the\n    agent-owned half of shared state real: `update_language` writes the\n    variable, the bridge emits the new snapshot, and this prompt reads it back\n    on the next turn.\n\n    It does NOT pick up a write from the browser. The bridge merges incoming\n    AG-UI state *under* the agent's variables --\n    `initial_state = (incoming.state or {}) | initial_vars` in\n    ag2/ag_ui/stream.py -- so `language` always resolves to the agent's value\n    and `agent.setState` from the Angular side is discarded. Verified end to\n    end: posting `state: {\"language\": \"spanish\"}` runs as english and the first\n    snapshot echoes english back. That is the Shared state guide's central\n    claim failing, and it is left as-is on purpose.\n    \"\"\"\n    return (\n        \"You are a helpful assistant. Answer with the available tools; each \"\n        \"tool's own description says when it applies. \"\n        f\"The user's preferred language is {language}. Reply in that language. \"\n        \"When the user asks to change it, call update_language.\"\n    )\n# shared state : prompt reads the shared variable end\n\n\n# quickstart : ag2 agent start\nagent = Agent(\n    \"CopilotKitAG2Agent\",\n    prompt=system_prompt,\n    config=_build_config(),\n    tools=[get_weather, update_language],\n    variables=INITIAL_VARIABLES,\n)\n# quickstart : ag2 agent end\n\napp = FastAPI(title=\"CopilotKit + AG2 (Python)\")\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"*\"],\n    allow_credentials=False,\n    allow_methods=[\"*\"],\n    allow_headers=[\"*\"],\n)\n\n\n@app.get(\"/health\")\ndef health() -> dict[str, str]:\n    \"\"\"Liveness probe for the harness's backend-health component.\"\"\"\n    return {\"status\": \"ok\", \"agent\": \"CopilotKitAG2Agent\", \"path\": \"/agent\"}\n\n\n# quickstart : mount the ag-ui stream start\nstream = AGUIStream(agent)\napp.mount(\"/agent\", stream.build_asgi())\n# quickstart : mount the ag-ui stream end\n\nif __name__ == \"__main__\":\n    uvicorn.run(\"main:app\", host=\"0.0.0.0\", port=8400, reload=True)\n",
  "../backend/pyproject.toml": "[project]\nname = \"backend\"\nversion = \"0.1.0\"\ndescription = \"AG2 agent exposed over AG-UI for the CopilotKit Angular harness.\"\nreadme = \"README.md\"\nrequires-python = \">=3.10,<3.15\"\ndependencies = [\n    \"ag2[ag-ui,openai]>=1.0.3,<2\",\n    \"fastapi>=0.128.0\",\n    \"httpx>=0.27.0\",\n    \"python-dotenv>=1.2.2\",\n    \"uvicorn>=0.40.0\",\n]\n\n[tool.uv]\npackage = false\n",
  "../backend/.env.example": "# AG2 talks to OpenAI directly. Copy this file to .env and fill it in.\nOPENAI_API_KEY=your_openai_api_key\nOPENAI_CHAT_MODEL_ID=gpt-4o-mini\n",
};

export function readSource(path: string): string {
  return SOURCES[path] ?? `// Source not generated for ${path}. Run: npm run gen:sources`;
}
